window.SAOMD_STORIES[410400901]={"id":410400901,"branches":[],"frames":[{"id":1,"order":1,"actions":[{"uid":"410400901:1:1","speaker":"Sinon","text":"So you're saying that what you\nthought was just a Halloween\nevent at the Dread Bastion...","pose":10040205,"background":"bg_18_inn_restaurant_morning","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"所以你是说你以为的只是恐惧堡垒的万圣节活动……"},{"uid":"410400901:1:2","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":2,"order":2,"actions":[{"uid":"410400901:2:1","speaker":"Sinon","text":"...actually turned into something\nmore.","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"……居然变成了更多的东西。"},{"uid":"410400901:2:2","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":3,"order":3,"actions":[{"uid":"410400901:3:1","speaker":"Asuna","text":"Kirito thinks that the reward\nbeing a Divine Object and all the\nmobs spawning everywhere...","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"桐人认为奖励是神器，而且所有小怪都在各处生成......"},{"uid":"410400901:3:2","speaker":"Yuuki","text":"","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":4,"order":4,"actions":[{"uid":"410400901:4:1","speaker":"Asuna","text":"...could be because of Alice and\nEugeo and the Divine Objects\nappearing here in ALO.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"...可能是因为爱丽丝和尤吉欧以及神器出现在ALO中。"},{"uid":"410400901:4:2","speaker":"Yuuki","text":"","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":5,"order":5,"actions":[{"uid":"410400901:5:1","speaker":"Sinon","text":"","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410400901:5:2","speaker":"Leafa","text":"So basically it's the Cardinal\nSystem automatically regulating\nfor these new factors.","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"所以基本上是卡迪纳尔系统自动调节这些新因素。"}]},{"id":6,"order":6,"actions":[{"uid":"410400901:6:1","speaker":"Asuna","text":"Yes, that's a good way of putting\nit. It's trying to change things\nto make them fit in ALO.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是的，这个说法很好。它试图改变一些东西，使它们适合 ALO。"},{"uid":"410400901:6:2","speaker":"Yuuki","text":"","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":7,"order":7,"actions":[{"uid":"410400901:7:1","speaker":"Yuuki","text":"That's not necessarily a bad thing\nin and of itself, right?","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"这本身并不一定是一件坏事，对吧？"}]},{"id":8,"order":8,"actions":[{"uid":"410400901:8:1","speaker":"Asuna","text":"No, that function is what\nauto-patches any bugs or\ncorrupt data, after all.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"不，毕竟这个功能是自动修补任何错误或损坏的数据的。"}]},{"id":9,"order":9,"actions":[{"uid":"410400901:9:1","speaker":"Asuna","text":"But in this case, it's not being\nhelpful.","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"但是对于这种情况来说，没有什么帮助。"},{"uid":"410400901:9:2","speaker":"Yuuki","text":"","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":10,"order":10,"actions":[{"uid":"410400901:10:1","speaker":"Leafa","text":"If it makes Alice and Eugeo part\nof this world, then they won't be\nable to go back to their own...","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"如果这让爱丽丝和尤吉欧成为这个世界的一部分，那么他们就无法回到自己的世界了……"},{"uid":"410400901:10:2","speaker":"Sinon","text":"","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":11,"order":11,"actions":[{"uid":"410400901:11:1","speaker":"Leafa","text":"And that would suck.","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"那就太糟糕了。"},{"uid":"410400901:11:2","speaker":"Sinon","text":"","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":12,"order":12,"actions":[{"uid":"410400901:12:1","speaker":"Asuna","text":"Yeah. I don't think we should say\nanything about it to those two.","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯。我认为我们不应该对这两个人说任何事情。"},{"uid":"410400901:12:2","speaker":"Yuuki","text":"","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":13,"order":13,"actions":[{"uid":"410400901:13:1","speaker":"Asuna","text":"We still don't have anything other\nthan our best guesses to go off\nof, anyway.","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"无论如何，除了我们最好的猜测之外，我们仍然没有任何其他的依据。"}]},{"id":14,"order":14,"actions":[{"uid":"410400901:14:1","speaker":"Yuuki","text":"Mum's the word! So, where are\nthose two? And Kirito?","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"妈妈的话！那么，这两个人在哪里？还有桐人？"}]},{"id":15,"order":15,"actions":[{"uid":"410400901:15:1","speaker":"Asuna","text":"Out investigating the Dread\nBastion.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"外出调查恐惧堡垒。"}]},{"id":16,"order":16,"actions":[{"uid":"410400901:16:1","speaker":"Asuna","text":"They're trying to find out if\nit's actually been changed back\nto its original Halloween state.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"他们正在尝试确定它是否真的变回了原来的万圣节状态。"},{"uid":"410400901:16:2","speaker":"Yuuki","text":"","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":17,"order":17,"actions":[{"uid":"410400901:17:1","speaker":"Silica","text":"Sorry to keep you waiting!\nI hope I'm not too late!","pose":10060408,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"抱歉让您久等了！我希望我还不算太晚！"},{"uid":"410400901:17:2","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410400901:17:3","speaker":"Sinon","text":"","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":18,"order":18,"actions":[{"uid":"410400901:18:1","speaker":"Leafa","text":"Hahaha, hate to break it to you,\nSilica, but you kinda are...","pose":100301042,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"哈哈哈，不想打扰你，西莉卡，但你有点……"}]},{"id":19,"order":19,"actions":[{"uid":"410400901:19:1","speaker":"Sinon","text":"Hehe, that's not true. We still\nhave plenty of time to enjoy\nHalloween.","pose":10040204,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"呵呵，这不是真的。我们还有充足的时间来享受万圣节。"},{"uid":"410400901:19:2","speaker":"Silica","text":"","pose":10060405,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":""},{"uid":"410400901:19:3","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":20,"order":20,"actions":[{"uid":"410400901:20:1","speaker":"Yuuki","text":"Yeah!","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"嗯！"},{"uid":"410400901:20:2","speaker":"Asuna","text":"","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":21,"order":21,"actions":[{"uid":"410400901:21:1","speaker":"Silica","text":"Um... I'm not sure I understand.","pose":10060402,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"嗯……我不太明白。"},{"uid":"410400901:21:2","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""},{"uid":"410400901:21:3","speaker":"Sinon","text":"","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":22,"order":22,"actions":[{"uid":"410400901:22:1","speaker":"Skeleton","text":"Clacka-clacka-clacka!","pose":1,"background":"bg_event_devil_castle_01","item":"","illustration":"","speaker_zh":"骷髅","text_zh":"叮叮当当！"},{"uid":"410400901:22:2","speaker":"Eugeo","text":"","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410400901:22:3","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410400901:22:4","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":23,"order":23,"actions":[{"uid":"410400901:23:1","speaker":"Eugeo","text":"Ahahaha, that skeleton has\na funny way of moving.","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"哈哈哈哈，那个骷髅的动作好搞笑。"}]},{"id":24,"order":24,"actions":[{"uid":"410400901:24:1","speaker":"Alice","text":"Just what is so \"funny\" about\nthat, Eugeo?","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"尤吉欧到底有什么“好笑”的？"}]},{"id":25,"order":25,"actions":[{"uid":"410400901:25:1","speaker":"Eugeo","text":"You don't think so, Alice?","pose":10530203,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"你不这么认为吗，爱丽丝？"}]},{"id":26,"order":26,"actions":[{"uid":"410400901:26:1","speaker":"Alice","text":"Hardly. Though these monsters are\nfar easier to defeat than before\nwe retrieved the Divine Object.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"几乎没有。尽管这些怪物比我们取回神器之前要容易击败得多。"}]},{"id":27,"order":27,"actions":[{"uid":"410400901:27:1","speaker":"Kirito","text":"You're right. They're much weaker\nthan when we first came here.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你说得对。他们比我们刚来的时候弱了很多。"}]},{"id":28,"order":28,"actions":[{"uid":"410400901:28:1","speaker":"Kirito","text":"So that must mean a Divine\nObject first strengthens existing\nmonsters...","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"也就是说，神物首先要强化现有的怪物……"}]},{"id":29,"order":29,"actions":[{"uid":"410400901:29:1","speaker":"Kirito","text":"...and then replaces them with\nits own monsters.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"……然后用自己的怪物代替。"}]},{"id":30,"order":30,"actions":[{"uid":"410400901:30:1","speaker":"Eugeo","text":"You mean that these here are the\noriginal residents of this castle?","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"你的意思是，这里的人是这座城堡原来的居民？"}]},{"id":31,"order":31,"actions":[{"uid":"410400901:31:1","speaker":"Kirito","text":"Yeah.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯。"}]},{"id":32,"order":32,"actions":[{"uid":"410400901:32:1","speaker":"Kirito","text":"But I don't think we'll be able\nto take back Aincrad just by\ndestroying them all.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"但是我认为仅仅将它们全部摧毁是无法夺回艾恩葛朗特的。"}]},{"id":33,"order":33,"actions":[{"uid":"410400901:33:1","speaker":"Kirito","text":"We should keep searching. There\nhas to be a way...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我们应该继续寻找。一定有办法..."},{"uid":"410400901:33:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410400901:33:3","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":34,"order":34,"actions":[{"uid":"410400901:34:1","speaker":"Yui","text":"Daddy, I have some information.","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"爸爸，我有一些信息。"}]},{"id":35,"order":35,"actions":[{"uid":"410400901:35:1","speaker":"Kirito","text":"What? Now?","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"什么？现在？"},{"uid":"410400901:35:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":36,"order":36,"actions":[{"uid":"410400901:36:1","speaker":"Alice","text":"What is going on?","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"怎么回事？"},{"uid":"410400901:36:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":37,"order":37,"actions":[{"uid":"410400901:37:1","speaker":"Kirito","text":"Uh, this is like...like a message\nfrom the gods of this world.","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"呃，这就像……来自这个世界的诸神的讯息一样。"},{"uid":"410400901:37:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":38,"order":38,"actions":[{"uid":"410400901:38:1","speaker":"Alice","text":"Ah, an oracle...","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"啊，神谕……"},{"uid":"410400901:38:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":39,"order":39,"actions":[{"uid":"410400901:39:1","speaker":"Kirito","text":"Y-Yeah, that. But I mean, it's\nnot as impressive as you\nmake it sound.","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是、是啊，那个。但我的意思是，它并不像你听起来那么令人印象深刻。"},{"uid":"410400901:39:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":40,"order":40,"actions":[{"uid":"410400901:40:1","speaker":"Kirito","text":"Let's see... Huh?!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我来看看……啊？！"},{"uid":"410400901:40:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":41,"order":41,"actions":[{"uid":"410400901:41:1","speaker":"Eugeo","text":"What do the gods say?","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"诸神怎么说？"},{"uid":"410400901:41:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":42,"order":42,"actions":[{"uid":"410400901:42:1","speaker":"Kirito","text":"Basically, um...they're giving us\npower over the Dread Bastion\nsince we defeated it first.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"基本上，嗯……自从我们首先击败了恐惧堡垒以来，他们就赋予了我们控制它的力量。"},{"uid":"410400901:42:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":43,"order":43,"actions":[{"uid":"410400901:43:1","speaker":"Kirito","text":"They say they're making the four\nof us the lords of the castle.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"他们说要让我们四个成为城堡的领主。"},{"uid":"410400901:43:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":44,"order":44,"actions":[{"uid":"410400901:44:1","speaker":"Alice","text":"What?! Explain!","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"什么？！解释！"},{"uid":"410400901:44:2","speaker":"Eugeo","text":"","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":45,"order":45,"actions":[{"uid":"410400901:45:1","speaker":"Kirito","text":"It means we have to protect this\ncastle from other play—other\nfairies who want to attack it.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这意味着我们必须保护这座城堡免受其他游戏的侵害——其他仙女想要攻击它。"},{"uid":"410400901:45:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":46,"order":46,"actions":[{"uid":"410400901:46:1","speaker":"Kirito","text":"It's defenders versus invaders...\nWait, so this event actually\nencourages PvP?!","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这是防御者对抗入侵者……等等，这个活动实际上是在鼓励PvP？！"},{"uid":"410400901:46:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":47,"order":47,"actions":[{"uid":"410400901:47:1","speaker":"Eugeo","text":"The gods have commanded us to\ndefend the Dread Bastion?","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"众神命令我们保卫恐惧堡垒？"},{"uid":"410400901:47:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":48,"order":48,"actions":[{"uid":"410400901:48:1","speaker":"Kirito","text":"Exactly. I bet Asuna got this\ninfo too...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"没错。我打赌亚丝娜也得到了这个信息......"},{"uid":"410400901:48:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":49,"order":49,"actions":[{"uid":"410400901:49:1","speaker":"Kirito","text":"I mean, I bet the oracle told her\nthe same thing, so we should meet\nup with her to talk about it.","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我的意思是，我打赌神谕也告诉了她同样的事情，所以我们应该和她见面谈谈这件事。"},{"uid":"410400901:49:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":50,"order":50,"actions":[{"uid":"410400901:50:1","speaker":"Alice","text":"What in the world is going to\nhappen now...?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"现在到底会发生什么……？"},{"uid":"410400901:50:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":51,"order":51,"actions":[{"uid":"410400901:51:1","speaker":"Asuna","text":"Yeah, I heard about the upcoming\nbattle too.","pose":10020905,"background":"bg_event_devil_castle_01","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯，我也听说了即将到来的战斗。"},{"uid":"410400901:51:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400901:51:3","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":52,"order":52,"actions":[{"uid":"410400901:52:1","speaker":"Kirito","text":"I thought you might have...\nHey, where are Sinon and the\nothers?","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我以为你可能……喂，诗乃他们在哪里？"}]},{"id":53,"order":53,"actions":[{"uid":"410400901:53:1","speaker":"Asuna","text":"Hehe, it seems like they got word\nthey'd be the ones attacking the\ncastle.","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呵呵，看来是他们接到消息要袭击城堡了。"}]},{"id":54,"order":54,"actions":[{"uid":"410400901:54:1","speaker":"Asuna","text":"Sinonon said they were gonna have\na strategy meeting about it, and\nthey left.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"诗诺说要开个战略会议，然后就走了。"}]},{"id":55,"order":55,"actions":[{"uid":"410400901:55:1","speaker":"Kirito","text":"Whoa, someone's super into this.","pose":10011503,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哇哦，有人超级喜欢这个。"}]},{"id":56,"order":56,"actions":[{"uid":"410400901:56:1","speaker":"Asuna","text":"Hahaha, they said we better watch\nout, 'cause this castle is as good\nas theirs.","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哈哈哈，他们说我们最好小心点，因为这座城堡和他们的一样好。"}]},{"id":57,"order":57,"actions":[{"uid":"410400901:57:1","speaker":"Asuna","text":"With so few PvP events in ALO\nlately, I think everyone's excited\nfor some competitive action.","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"最近ALO的PvP活动很少，我想大家都对一些竞技活动感到兴奋。"}]},{"id":58,"order":58,"actions":[{"uid":"410400901:58:1","speaker":"Kirito","text":"It has been a while. I'm looking\nforward to this too. It's not every\nday we get to play defense.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"好久不见了。我也很期待这个。我们并不是每天都能进行防守。"}]},{"id":59,"order":59,"actions":[{"uid":"410400901:59:1","speaker":"Kirito","text":"Plus, being a dread lord of the\nDread Bastion sounds kinda\nawesome, don't you think?","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"另外，成为恐惧堡垒的恐惧领主听起来有点棒，你不觉得吗？"}]},{"id":60,"order":60,"actions":[{"uid":"410400901:60:1","speaker":"Asuna","text":"Hahaha...\nBut you know that makes Sinonon\nand the others our sworn enemies.","pose":100209042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哈哈哈……但是你知道，这让诗乃他们成为了我们的死敌。"}]},{"id":61,"order":61,"actions":[{"uid":"410400901:61:1","speaker":"Asuna","text":"If we aren't careful, they'll take\nus down in no time at all.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"一不小心，他们很快就会把我们打倒。"}]},{"id":62,"order":62,"actions":[{"uid":"410400901:62:1","speaker":"Kirito","text":"Yeah, but we've got Alice and\nEugeo on our side. I'd say this\ncastle's as good as defended.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是的，但是我们这边有爱丽丝和尤吉欧。我想说这座城堡防守得很好。"}]},{"id":63,"order":63,"actions":[{"uid":"410400901:63:1","speaker":"Kirito","text":"Well, but I guess it is PvP...\nWin or lose, we'll be going back\nto Aincrad after this, huh?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯，不过我猜应该是PvP……无论输赢，之后我们都会回到艾恩葛朗特吧？"}]},{"id":64,"order":64,"actions":[{"uid":"410400901:64:1","speaker":"Yui","text":"I think so. It is the last part of\nthe Halloween event, so once\nthe time limit elapses, that's it.","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"我想是的。这是万圣节活动的最后一部分，所以一旦时间限制过去，就结束了。"}]},{"id":65,"order":65,"actions":[{"uid":"410400901:65:1","speaker":"Kirito","text":"I was afraid of that... How are we\ngoing to explain this to Alice and\nEugeo?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我就怕这个……怎么跟爱丽丝和尤吉欧解释呢？"}]},{"id":66,"order":66,"actions":[{"uid":"410400901:66:1","speaker":"Asuna","text":"Good question... We can't very\nwell tell them it doesn't matter\nif we succeed or not.","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"好问题……我们不能很好地告诉他们成功与否并不重要。"}]},{"id":67,"order":67,"actions":[{"uid":"410400901:67:1","speaker":"Asuna","text":"If she hears that, there's no way\nAlice will want any part of it.","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"如果她听到了，爱丽丝就不可能想要任何一部分。"}]},{"id":68,"order":68,"actions":[{"uid":"410400901:68:1","speaker":"Asuna","text":"But I don't want to lie, either.\nIt feels too duplicitous.","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"但我也不想撒谎。感觉太两面性了。"}]},{"id":69,"order":69,"actions":[{"uid":"410400901:69:1","speaker":"Yui","text":"Can't you just keep those two from\ntaking part in any quest that's\nnot related to the Divine Objects?","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"能不能让这两个人不要再参与任何与神器无关的任务了？"}]},{"id":70,"order":70,"actions":[{"uid":"410400901:70:1","speaker":"Kirito","text":"Well, we could, but then that'd\njust leave Asuna and me to\ndefend the Dread Bastion...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"好吧，我们可以，但是那样的话就只剩下亚丝娜和我来保卫恐惧堡垒了……"}]},{"id":71,"order":71,"actions":[{"uid":"410400901:71:1","speaker":"Kirito","text":"Talk about being stuck between\na rock and a hard place... Well,\nI guess we don't have a choice.","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"说到进退两难……好吧，我想我们别无选择。"}]},{"id":72,"order":72,"actions":[{"uid":"410400901:72:1","speaker":"Asuna","text":"It won't be easy, but the two of\nus are just going to have to\nprotect this place on our own.","pose":10020909,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"这并不容易，但我们两个人必须靠自己的力量来保护这个地方。"}]},{"id":73,"order":73,"actions":[{"uid":"410400901:73:1","speaker":"Kirito","text":"You're right.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你说得对。"},{"uid":"410400901:73:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400901:73:3","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":74,"order":74,"actions":[{"uid":"410400901:74:1","speaker":"Eugeo","text":"Of course I'm helping!","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我当然帮忙！"},{"uid":"410400901:74:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":75,"order":75,"actions":[{"uid":"410400901:75:1","speaker":"Alice","text":"And I will too.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我也会的。"},{"uid":"410400901:75:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":76,"order":76,"actions":[{"uid":"410400901:76:1","speaker":"Asuna","text":"What?!","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"什么？！"},{"uid":"410400901:76:2","speaker":"Kirito","text":"","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":77,"order":77,"actions":[{"uid":"410400901:77:1","speaker":"Kirito","text":"You know all you have to do is\nwait a little and you'll go back\nto Aincrad, right?","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你知道只要稍等一下，你就会回到艾恩葛朗特，对吧？"},{"uid":"410400901:77:2","speaker":"Asuna","text":"","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":78,"order":78,"actions":[{"uid":"410400901:78:1","speaker":"Eugeo","text":"But we have become the leaders\nof the dread hordes!","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"但我们已经成为了恐惧部落的首领！"},{"uid":"410400901:78:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":79,"order":79,"actions":[{"uid":"410400901:79:1","speaker":"Eugeo","text":"We can't very well abandon them\nwhen they need us the most!","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我们不能在他们最需要我们的时候抛弃他们！"}]},{"id":80,"order":80,"actions":[{"uid":"410400901:80:1","speaker":"Alice","text":"There is much prohibited in this\nworld that we do not quite\nunderstand.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这个世界上有很多禁忌我们不太了解。"}]},{"id":81,"order":81,"actions":[{"uid":"410400901:81:1","speaker":"Alice","text":"We do not know where to go or\nwhat to do if we do not join the\nfight with you.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"如果不和你一起战斗，我们不知道该去哪里，做什么。"}]},{"id":82,"order":82,"actions":[{"uid":"410400901:82:1","speaker":"Alice","text":"The mere thought of such tedium\nmakes me shudder.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"光是想到这样的单调就让我不寒而栗。"}]},{"id":83,"order":83,"actions":[{"uid":"410400901:83:1","speaker":"Alice","text":"Our time would be much better\nspent honing our swords with\nyou in battle.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我们的时间还不如和你一起磨刀霍霍呢。"},{"uid":"410400901:83:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":84,"order":84,"actions":[{"uid":"410400901:84:1","speaker":"Kirito","text":"Eugeo... Alice...","pose":10011503,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"尤吉欧... 爱丽丝..."},{"uid":"410400901:84:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":85,"order":85,"actions":[{"uid":"410400901:85:1","speaker":"Alice","text":"And in any case, I believe it best\nto obey the will of the gods\nof this world.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"而且无论如何，我认为服从这个世界诸神的意志是最好的。"},{"uid":"410400901:85:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":86,"order":86,"actions":[{"uid":"410400901:86:1","speaker":"Eugeo","text":"Hear, hear.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"听听听。"},{"uid":"410400901:86:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":87,"order":87,"actions":[{"uid":"410400901:87:1","speaker":"Asuna","text":"Thank you both so much! We're so\nglad that you want to help us.\nAren't we, Kirito?","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"非常感谢两位！我们很高兴您愿意帮助我们。我们不是吗，桐人？"},{"uid":"410400901:87:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":88,"order":88,"actions":[{"uid":"410400901:88:1","speaker":"Kirito","text":"Uh, yeah! Totally!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"呃，是啊！完全！"}]},{"id":89,"order":89,"actions":[{"uid":"410400901:89:1","speaker":"Sinon","text":"Here we are again...\nThe Dread Bastion.","pose":10040207,"background":"bg_event_devil_castle_01","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"我们又来了……恐惧堡垒。"},{"uid":"410400901:89:2","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":90,"order":90,"actions":[{"uid":"410400901:90:1","speaker":"Leafa","text":"Hehe, but who'd have thought we'd\ncome back as the invading force?","pose":10030104,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"呵呵，但谁能想到我们会以侵略军的身份回来呢？"},{"uid":"410400901:90:2","speaker":"Sinon","text":"","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":91,"order":91,"actions":[{"uid":"410400901:91:1","speaker":"Yuuki","text":"Ooh, I can't wait! It's been ages\nsince we had a good fight with\nKirito and Asuna!","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"哎呀，我等不及了！我们已经好久没有和桐人和亚丝娜好好打架了！"},{"uid":"410400901:91:2","speaker":"Silica","text":"","pose":10060405,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":""}]},{"id":92,"order":92,"actions":[{"uid":"410400901:92:1","speaker":"Silica","text":"It's a little nerve-racking,\nisn't it?","pose":10060403,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"有点伤脑筋，不是吗？"},{"uid":"410400901:92:2","speaker":"Yuuki","text":"","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":""}]},{"id":93,"order":93,"actions":[{"uid":"410400901:93:1","speaker":"Sinon","text":"Don't worry. We have plenty of\nplayers to help us capture the\ncastle this time.","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"别担心。这次我们有足够的玩家来帮助我们占领城堡。"},{"uid":"410400901:93:2","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":94,"order":94,"actions":[{"uid":"410400901:94:1","speaker":"Sinon","text":"Destroying all those demons should\nbe a piece of cake with their help.","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"有他们的帮助，消灭那些恶魔应该是小菜一碟。"}]},{"id":95,"order":95,"actions":[{"uid":"410400901:95:1","speaker":"Leafa","text":"You sound SO pumped for this,\nSinon!","pose":10030104,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"你听起来很兴奋，诗乃！"}]},{"id":96,"order":96,"actions":[{"uid":"410400901:96:1","speaker":"Sinon","text":"W-Well, I don't think I'm any more\nor less excited than usual...","pose":100402031,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"呃、呃，我觉得我没有比平时更兴奋或更不兴奋……"}]},{"id":97,"order":97,"actions":[{"uid":"410400901:97:1","speaker":"Player","text":"Okay, everyone's here!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家","text_zh":"好了，大家都到了！"},{"uid":"410400901:97:2","speaker":"Sinon","text":"","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""},{"uid":"410400901:97:3","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":98,"order":98,"actions":[{"uid":"410400901:98:1","speaker":"Yuuki","text":"Looks like they're ready.","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"看来已经准备好了。"},{"uid":"410400901:98:2","speaker":"Silica","text":"","pose":10060405,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":""}]},{"id":99,"order":99,"actions":[{"uid":"410400901:99:1","speaker":"Sinon","text":"Then let's get this party started.\nAlright, everyone, take your\npositions!","pose":10040207,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"那么我们就开始这场派对吧。好啦，大家各就各位！"},{"uid":"410400901:99:2","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":100,"order":100,"actions":[{"uid":"410400901:100:1","speaker":"Kirito","text":"You're telling me the enemy is\nalready at the gates, Eugeo?!","pose":10011508,"background":"bg_event_devil_castle_02","item":"","illustration":"","speaker_zh":"桐人","text_zh":"尤吉欧，你是说敌人已经到了门口？！"},{"uid":"410400901:100:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":101,"order":101,"actions":[{"uid":"410400901:101:1","speaker":"Eugeo","text":"Yes. I saw your friends too.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"是的。我也看到了你的朋友。"},{"uid":"410400901:101:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":102,"order":102,"actions":[{"uid":"410400901:102:1","speaker":"Eugeo","text":"I think they've formed platoons\nwith other fairies and will be\npressing in on us from all sides.","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我想他们已经和其他妖精组成了排，会从四面八方逼近我们。"},{"uid":"410400901:102:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":103,"order":103,"actions":[{"uid":"410400901:103:1","speaker":"Kirito","text":"Makes sense they'd attempt a\nsiege. Pretty cut-and-dry strategy\nfor taking a castle, really...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"他们尝试围攻是有道理的。夺取城堡的相当简单的策略，真的......"},{"uid":"410400901:103:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":104,"order":104,"actions":[{"uid":"410400901:104:1","speaker":"Alice","text":"What is our plan of defense? Shall\nwe split up as well and each take\na group to counter attack?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我们的防御计划是什么？我们也分头行动，各自带一组去反击吗？"},{"uid":"410400901:104:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":105,"order":105,"actions":[{"uid":"410400901:105:1","speaker":"Kirito","text":"I don't think so. The four of us\nare the lords of the Bastion now.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我不这么认为。我们四个人现在是堡垒的领主了。"},{"uid":"410400901:105:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":106,"order":106,"actions":[{"uid":"410400901:106:1","speaker":"Kirito","text":"Splitting up makes us way more\nvulnerable to defeat, so we should\nstay together.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"分手会让我们更容易失败，所以我们应该在一起。"},{"uid":"410400901:106:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":107,"order":107,"actions":[{"uid":"410400901:107:1","speaker":"Alice","text":"Then what do you suggest?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"那你有什么建议呢？"},{"uid":"410400901:107:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":108,"order":108,"actions":[{"uid":"410400901:108:1","speaker":"Kirito","text":"Ha ha, well...","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哈哈，那个……"},{"uid":"410400901:108:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":109,"order":109,"actions":[{"uid":"410400901:109:1","speaker":"Kirito","text":"Now that we're lords of the Dread\nBastion, we're endowed with some\npretty impressive powers.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"现在我们是恐惧堡垒的领主，我们被赋予了一些相当令人印象深刻的力量。"}]},{"id":110,"order":110,"actions":[{"uid":"410400901:110:1","speaker":"Kirito","text":"Let's put those powers to good\nuse.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"让我们好好利用这些力量吧。"}]},{"id":111,"order":111,"actions":[{"uid":"410400901:111:1","speaker":"Kirito","text":"Hehe... Hahahaha!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"呵呵……哈哈哈哈！"},{"uid":"410400901:111:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":112,"order":112,"actions":[{"uid":"410400901:112:1","speaker":"Alice","text":"...?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"...?"},{"uid":"410400901:112:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":113,"order":113,"actions":[{"uid":"410400901:113:1","speaker":"Sinon","text":"Attack!\nArchers, forward!","pose":10040201,"background":"bg_event_devil_castle_01","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"攻击！弓箭手，前进！"}]},{"id":114,"order":114,"actions":[{"uid":"410400901:114:1","speaker":"Players","text":"HYAAAH!","pose":3,"background":"","item":"","illustration":"","speaker_zh":"玩家","text_zh":"哈啊！"}]},{"id":115,"order":115,"actions":[{"uid":"410400901:115:1","speaker":"Leafa","text":"Sinon, the werewolves are getting\ncloser!","pose":10030101,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"诗乃，狼人越来越近了！"}]},{"id":116,"order":116,"actions":[{"uid":"410400901:116:1","speaker":"Sinon","text":"Don't worry. The archers can\nhandle them.","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"别担心。弓箭手可以对付他们。"}]},{"id":117,"order":117,"actions":[{"uid":"410400901:117:1","speaker":"Sinon","text":"You go help Silica and the others!","pose":10040207,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"你去帮助西莉卡他们吧！"}]},{"id":118,"order":118,"actions":[{"uid":"410400901:118:1","speaker":"Leafa","text":"Roger that!","pose":10030107,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"明白！"}]},{"id":119,"order":119,"actions":[{"uid":"410400901:119:1","speaker":"Yuuki","text":"Hehe, you're getting good at this\nwhole commanding-an-army\nthing, Sinon!","pose":10050104,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"呵呵，指挥军队这事越来越拿手了，诗乃！"}]},{"id":120,"order":120,"actions":[{"uid":"410400901:120:1","speaker":"Sinon","text":"It's not on purpose, Yuuki! For\nsome reason, people always end\nup relying on me for orders.","pose":100402031,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"不是故意的，优纪！出于某种原因，人们最终总是依赖我来发号施令。"}]},{"id":121,"order":121,"actions":[{"uid":"410400901:121:1","speaker":"Sinon","text":"Even though I'm not really\nthe leader type...","pose":10040206,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"虽然我不是真正的领导型..."}]},{"id":122,"order":122,"actions":[{"uid":"410400901:122:1","speaker":"Yuuki","text":"I guess most of the time, Kirito\nor Asuna take control of the\nsituation, huh?","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"我猜大部分时候都是桐人或者亚丝娜掌控局面吧？"}]},{"id":123,"order":123,"actions":[{"uid":"410400901:123:1","speaker":"Sinon","text":"Except this time they're our\nenemies. Heh, I hope we get\nto fight them soon.","pose":10040204,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"只不过这次他们是我们的敌人。呵呵，希望我们能尽快和他们战斗。"}]},{"id":124,"order":124,"actions":[{"uid":"410400901:124:1","speaker":"Yuuki","text":"Well, they're the bosses, so we\ngotta get though these monsters\nfirst and get into the castle!","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"好吧，他们是boss，所以我们得先解决掉这些怪物，然后进入城堡！"}]},{"id":125,"order":125,"actions":[{"uid":"410400901:125:1","speaker":"Sinon","text":"Yeah... It's crazy to think\nthey're the ones commanding\nall these terrifying creatures...","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"是啊...认为他们是指挥所有这些可怕生物的人真是太疯狂了..."}]},{"id":126,"order":126,"actions":[{"uid":"410400901:126:1","speaker":"Yuuki","text":"Kinda goes along with the whole\n\"dread lord\" thing. Otherwise this\nfight would be too one-sided!","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"有点同意整个“恐惧领主”的事情。不然这一战就太一边倒了！"}]},{"id":127,"order":127,"actions":[{"uid":"410400901:127:1","speaker":"Sinon","text":"True. I thought it'd be easy since\nit was all of us against just the\nfour of them, but guess not.","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"确实如此。我以为这会很容易，因为我们所有人都只对抗他们四个人，但我猜不是。"}]},{"id":128,"order":128,"actions":[{"uid":"410400901:128:1","speaker":"Yuuki","text":"I'm glad it turned out this way!\nI love the challenge!","pose":10050104,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"我很高兴变成这样！我喜欢挑战！"}]},{"id":129,"order":129,"actions":[{"uid":"410400901:129:1","speaker":"Sinon","text":"Hehe, you would.","pose":10040204,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"呵呵，你会的。"}]},{"id":130,"order":130,"actions":[{"uid":"410400901:130:1","speaker":"Yuuki","text":"Right, I should get to my position\ntoo. Catch up with you later,\nSinon!","pose":10050105,"background":"","item":"","illustration":"","speaker_zh":"优纪","text_zh":"对了，我也该到我的位置了。稍后再见，诗乃！"}]},{"id":131,"order":131,"actions":[{"uid":"410400901:131:1","speaker":"Sinon","text":"I'm counting on you, Yuuki!","pose":10040204,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"我就靠你了，优纪！"}]},{"id":132,"order":132,"actions":[{"uid":"410400901:132:1","speaker":"Silica","text":"Take this!","pose":10060401,"background":"bg_event_devil_castle_01","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"拿着这个！"},{"uid":"410400901:132:2","speaker":"Pina","text":"","pose":20030105,"background":"","item":"","illustration":"","speaker_zh":"毕娜","text_zh":""}]},{"id":133,"order":133,"actions":[{"uid":"410400901:133:1","speaker":"Demon","text":"GRARR!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"恶魔","text_zh":"嘎嘎！"}]},{"id":134,"order":134,"actions":[{"uid":"410400901:134:1","speaker":"Silica","text":"Aww, these demons are actually\nkinda cute... It almost makes me\nsad I have to destroy them.","pose":10060406,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"哇哦，这些恶魔其实有点可爱……不得不消灭它们，这让我几乎很难过。"}]},{"id":135,"order":135,"actions":[{"uid":"410400901:135:1","speaker":"Pina","text":"Chiiirp...","pose":20030106,"background":"","item":"","illustration":"","speaker_zh":"毕娜","text_zh":"啾——！"}]},{"id":136,"order":136,"actions":[{"uid":"410400901:136:1","speaker":"Silica","text":"You're right, Pina. This is war,\nafter all.","pose":10060407,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"你说得对，毕娜。毕竟这是战争。"}]},{"id":137,"order":137,"actions":[{"uid":"410400901:137:1","speaker":"Silica","text":"I have to harden my heart and\nfight!","pose":10060407,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"我要硬着心去奋斗！"}]},{"id":138,"order":138,"actions":[{"uid":"410400901:138:1","speaker":"Pina","text":"Chirp chiiirp!","pose":20030104,"background":"","item":"","illustration":"","speaker_zh":"毕娜","text_zh":"叽叽喳喳！"}]},{"id":139,"order":139,"actions":[{"uid":"410400901:139:1","speaker":"Vampire","text":"I vant to suck your bloood!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"吸血鬼","text_zh":"我要吸你的血！"}]},{"id":140,"order":140,"actions":[{"uid":"410400901:140:1","speaker":"Silica","text":"Aaaaahhh!","pose":10060408,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"啊啊啊啊！"}]},{"id":141,"order":141,"actions":[{"uid":"410400901:141:1","speaker":"Leafa","text":"Suck on THIS!","pose":10030101,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"吸这个！"},{"uid":"410400901:141:2","speaker":"Pina","text":"","pose":20030105,"background":"","item":"","illustration":"","speaker_zh":"毕娜","text_zh":""}]},{"id":142,"order":142,"actions":[{"uid":"410400901:142:1","speaker":"Vampire","text":"Aaauughhhh!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"吸血鬼","text_zh":"啊啊啊啊！"}]},{"id":143,"order":143,"actions":[{"uid":"410400901:143:1","speaker":"Leafa","text":"Are you okay, Silica?!","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"西莉卡，你还好吗？！"}]},{"id":144,"order":144,"actions":[{"uid":"410400901:144:1","speaker":"Silica","text":"Thanks to you, I am, Leafa!","pose":10060404,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"谢谢你，我是，莉法！"}]},{"id":145,"order":145,"actions":[{"uid":"410400901:145:1","speaker":"Vampire","text":"Hnnghh... I am not finished vith\nyou yet!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"吸血鬼","text_zh":"哼哼……我还没和你说完呢！"}]},{"id":146,"order":146,"actions":[{"uid":"410400901:146:1","speaker":"Vampire","text":"HAAAH!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"吸血鬼","text_zh":"哈哈哈！"}]},{"id":147,"order":147,"actions":[{"uid":"410400901:147:1","speaker":"Leafa","text":"What?!","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"什么？！"}]},{"id":148,"order":148,"actions":[{"uid":"410400901:148:1","speaker":"Leafa","text":"Aaaahhhhh!","pose":10030103,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"啊啊啊啊啊！"}]},{"id":149,"order":149,"actions":[{"uid":"410400901:149:1","speaker":"Silica","text":"Leafa!","pose":10060408,"background":"","item":"","illustration":"","speaker_zh":"西莉卡","text_zh":"莉法！"},{"uid":"410400901:149:2","speaker":"Pina","text":"","pose":20030108,"background":"","item":"","illustration":"","speaker_zh":"毕娜","text_zh":""},{"uid":"410400901:149:3","speaker":"Leafa","text":"","pose":10030103,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":150,"order":150,"actions":[{"uid":"410400901:150:1","speaker":"Kirito","text":"Take this!","pose":10011501,"background":"bg_event_devil_castle_02","item":"","illustration":"","speaker_zh":"桐人","text_zh":"拿着这个！"},{"uid":"410400901:150:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":151,"order":151,"actions":[{"uid":"410400901:151:1","speaker":"Player","text":"Gaaaah!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家","text_zh":"啊啊啊！"}]},{"id":152,"order":152,"actions":[{"uid":"410400901:152:1","speaker":"Kirito","text":"Phew... I can't believe all the\nfronts they're fighting us on.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"呼……我不敢相信他们在所有战线上与我们作战。"}]},{"id":153,"order":153,"actions":[{"uid":"410400901:153:1","speaker":"Kirito","text":"Guess I should've expected this\nfrom Sinon.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我猜我应该预料到诗乃会这么说。"}]},{"id":154,"order":154,"actions":[{"uid":"410400901:154:1","speaker":"Player","text":"I'm not done yet...","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家","text_zh":"我还没说完呢..."}]},{"id":155,"order":155,"actions":[{"uid":"410400901:155:1","speaker":"Kirito","text":"What?!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"什么？！"}]},{"id":156,"order":156,"actions":[{"uid":"410400901:156:1","speaker":"Player","text":"Try dodging THIS!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家","text_zh":"尝试躲避这个！"}]},{"id":157,"order":157,"actions":[{"uid":"410400901:157:1","speaker":"Kirito","text":"Throwing knives?!","pose":100115082,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"飞刀？！"}]},{"id":158,"order":158,"actions":[{"uid":"410400901:158:1","speaker":"Asuna","text":"Watch out, Kirito!","pose":10020901,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"小心桐人！"}]},{"id":159,"order":159,"actions":[{"uid":"410400901:159:1","speaker":"Asuna","text":"Gaah!","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嘎啊！"}]},{"id":160,"order":160,"actions":[{"uid":"410400901:160:1","speaker":"Player","text":"Tch... It may have only grazed\nyou, but that's all it takes.","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家","text_zh":"切……它可能只是擦伤了你，但仅此而已。"}]},{"id":161,"order":161,"actions":[{"uid":"410400901:161:1","speaker":"Kirito","text":"Are you all right, Asuna?!","pose":100115012,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"亚丝娜，你还好吗？！"}]},{"id":162,"order":162,"actions":[{"uid":"410400901:162:1","speaker":"Asuna","text":"Yeah, I-I'm...fine...\nI...","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是啊，我、我……很好……我……"}]},{"id":163,"order":163,"actions":[{"uid":"410400901:163:1","speaker":"Kirito","text":"A-Asuna? Hey! Hang in there!","pose":100115082,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"A-亚丝娜？嘿！坚持住！"}]},{"id":164,"order":164,"actions":[{"uid":"410400901:164:1","speaker":"Asuna","text":"S-Strange... I can't...\nI can't seem to stand...","pose":100209092,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"奇怪……我不能……我好像受不了……"}]},{"id":165,"order":165,"actions":[{"uid":"410400901:165:1","speaker":"Kirito","text":"Check your status. Something's\ngotta be up!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"查看状态。一定有事发生！"}]},{"id":166,"order":166,"actions":[{"uid":"410400901:166:1","speaker":"Asuna","text":"Okay... Huh? I've never seen this\nkind of status ailment before...","pose":10020903,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"好吧……嗯？我以前从未见过这种状态异常......"}]},{"id":167,"order":167,"actions":[{"uid":"410400901:167:1","speaker":"Asuna","text":"Have you ever heard of\n\"Fatal Poison\"?","pose":10020903,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"你听说过《致命毒药》吗？"}]},{"id":168,"order":168,"actions":[{"uid":"410400901:168:1","speaker":"Kirito","text":"I knew it, that knife was laced\nwith something.","pose":10011501,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我就知道，那把刀上缠着什么东西。"}]},{"id":169,"order":169,"actions":[{"uid":"410400901:169:1","speaker":"Kirito","text":"We gotta cure it. I've got plenty\nof antidotes if you need one.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我们得治愈它。如果你需要的话，我有很多解药。"}]},{"id":170,"order":170,"actions":[{"uid":"410400901:170:1","speaker":"Asuna","text":"Th-Thanks...","pose":10020909,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"谢谢、谢谢……"}]}]};
